#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# BP+ split, one replay run on 11 of box3900x's 12 cores (22 threads): the test node on CPUs 0-10,12-22, the source node on core 11 (CPUs 11,23).
# The control box restores the working DB to stressnet_h3103300c (height 3,103,300) before each run (snapctl.sh restore).
# A stock beta31 source node on the synced snapshot copy (127.0.0.1:28180, pinned to CPUs 4-11) serves the blocks; the
# test node runs pinned to CPUs 0-3 (four physical cores; their SMT siblings 12-15 stay idle) with --max-concurrency 4
# and --show-time-stats 1 (logged at blockchain:INFO), until its height passes END. Governor performance during the run, schedutil restored after.
# Samples every second: unix time, height (RPC), the node's utime+stime ticks; pidstat -t -u every 2 s (per thread).
# PERF=1: one DWARF call-graph profile (49 Hz, 8 KB stacks, CLOCK_MONOTONIC) of PERF_S s once the height reaches PERF_AT.
# usage: [END=<height>] [PERF=1 PERF_AT=<height> PERF_S=<s>] bpp_run.sh <name> <monerod>    Marker BPP_RUN_DONE in run.log.
set -u
name=$1; BIN=$2
A=$HOME/work/research-artifacts; O=$A/bpp/runs/$name; DD=$HOME/work/chains/stressnet
SRCDD=$A/snapshots/stressnet_synced_h3123270; STOCK=$HOME/work/monero-fcmp/build/beta31/bin/monerod
END=${END:-3103500}; START=3103300; RUN_TIMEOUT=${RUN_TIMEOUT:-7200}
[ -x "$BIN" ] && [ -x "$STOCK" ] && [ -f "$SRCDD/testnet/lmdb/data.mdb" ] && [ -f "$DD/testnet/lmdb/data.mdb" ] || { echo "ABORT: not on the work box"; exit 1; }
[ -e "$O" ] && { echo "ABORT: $O exists"; exit 1; }
mkdir -p $O; L=$O/run.log
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
GOV0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
fin() { sudo cpupower -c all frequency-set -g $GOV0 > /dev/null 2>&1; log "governor back to $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)"; log "BPP_RUN_DONE $1"; exit 0; }
log "start $name; binary $(sha256sum $BIN | cut -c1-16) $($BIN --version | tail -1); end $END"
pgrep -u $USER -x monerod > /dev/null && { log "ABORT a monerod is running"; fin abort; }
pgrep -x shadow > /dev/null && { log "ABORT shadow lanes are running"; fin abort; }
log "load $(cut -d' ' -f1-3 /proc/loadavg); free GB $(df --output=avail -BG $HOME | tail -1)"
rm -f $DD/testnet/lmdb/lock.mdb $SRCDD/testnet/lmdb/lock.mdb
sync; sudo sysctl -q vm.drop_caches=3
sudo cpupower -c all frequency-set -g performance > /dev/null && log "governor $GOV0 -> performance"
# the source node, off the test node's cores
(setsid nohup taskset -c 11,23 nice -n 5 $STOCK --testnet --data-dir $SRCDD --p2p-bind-ip 127.0.0.1 --p2p-bind-port 28180 --hide-my-port \
  --out-peers 0 --in-peers 4 --add-exclusive-node 127.0.0.1:1 --no-zmq --non-interactive --no-igd --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28181 \
  --log-file $O/source.log --log-level 0 > $O/source.stdout 2>&1 &)
for i in $(seq 1 300); do curl -s -m 3 http://127.0.0.1:28181/get_height | grep -q '"height"' && break; sleep 1; done
sh=$(curl -s -m 5 http://127.0.0.1:28181/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$')
[ "${sh:-0}" -gt $END ] || { log "ABORT source height ${sh:-none}"; curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null; fin abort; }
log "source node up, height $sh"
# the test node, pinned
t0=$(date +%s)
(setsid nohup taskset -c 0-10,12-22 $BIN --testnet --data-dir $DD --add-exclusive-node 127.0.0.1:28180 --p2p-bind-ip 127.0.0.1 --no-igd --no-zmq \
  --non-interactive --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28081 --show-time-stats 1 \
  --log-file $O/node.log --log-level 0,blockchain:INFO > $O/node.stdout 2>&1 &)
NP=; for i in $(seq 1 120); do NP=$(pgrep -u $USER -f "^$BIN --testnet --data-dir $DD " | head -1); [ -n "$NP" ] && break; sleep 0.5; done
[ -n "$NP" ] || { log "ABORT the test node did not start"; curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null; fin abort; }
log "test node pid $NP; affinity $(taskset -pc $NP 2>&1 | sed 's/.*: //')"
pidstat -t -u -p $NP 2 > $O/pidstat.txt 2>&1 &
PS=$!
echo "unix_s,height,ticks" > $O/samples.csv
( while kill -0 $NP 2>/dev/null; do
    hh=$(curl -s -m 2 http://127.0.0.1:28081/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$')
    tk=$(awk '{print $14 + $15}' /proc/$NP/stat 2>/dev/null)
    echo "$(date +%s.%N),${hh:-},${tk:-}" >> $O/samples.csv
    sleep 1
  done ) &
SP=$!
h=0; why=timeout; PF=
while [ $(( $(date +%s) - t0 )) -lt $RUN_TIMEOUT ]; do
  sleep 5
  kill -0 $NP 2>/dev/null || { why=exited; break; }
  h=$(curl -s -m 5 http://127.0.0.1:28081/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$'); h=${h:-0}
  [ "$h" -gt $END ] && { why=end; break; }
  if [ -n "${PERF:-}" ] && [ -z "$PF" ] && [ "$h" -ge "${PERF_AT:-3103310}" ]; then
    sudo perf record -F 49 -k CLOCK_MONOTONIC --call-graph dwarf,8192 -p $NP -o $O/perf.data -- sleep ${PERF_S:-60} > $O/perf.out 2>&1 &
    PF=$!; log "perf started at height $h"
  fi
done
[ -n "$PF" ] && { wait $PF; sudo chown $USER: $O/perf.data; log "perf done: $(grep -o "Captured.*" $O/perf.out | head -1)"; }
log "end: $why at height $h after $(( $(date +%s) - t0 )) s from launch"
top=$(curl -s -m 10 http://127.0.0.1:28081/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_block_header_by_height","params":{"height":'$END'}}' | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
src=$(curl -s -m 10 http://127.0.0.1:28181/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_block_header_by_height","params":{"height":'$END'}}' | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
log "block $END: node $top source $src $([ -n "$top" ] && [ "$top" = "$src" ] && echo HASH_OK || echo HASH_BAD)"
curl -s -m 30 http://127.0.0.1:28081/stop_daemon > /dev/null
for i in $(seq 1 300); do kill -0 $NP 2>/dev/null || break; sleep 1; done
kill -0 $NP 2>/dev/null && { log "test node still up, TERM"; kill -TERM $NP; sleep 30; }
kill $SP $PS 2>/dev/null; wait $SP $PS 2>/dev/null
curl -s -m 30 http://127.0.0.1:28181/stop_daemon > /dev/null
for i in $(seq 1 300); do pgrep -u $USER -x monerod > /dev/null || break; sleep 1; done
log "monerod processes left: $(pgrep -u $USER -x monerod | wc -l)"
rm -f $DD/testnet/lmdb/lock.mdb
log "node log: ERROR $(grep -c '	ERROR	' $O/node.log), time-stats lines $(grep -c 'p/t:' $O/node.log)"
fin $why
